CREATE POLICY evidence_session_security ON storage.objects AS RESTRICTIVE TO authenticated USING (((bucket_id <> 'transfer-evidence'::text) OR (public.staff_session_unlocked() AND public.staff_mfa_satisfied()))) WITH CHECK (((bucket_id <> 'transfer-evidence'::text) OR (public.staff_session_unlocked() AND public.staff_mfa_satisfied())));
CREATE POLICY transfer_evidence_delete ON storage.objects FOR DELETE TO authenticated USING (((bucket_id = 'transfer-evidence'::text) AND public.can_access_transfer_evidence(name, 'delete'::text)));
CREATE POLICY transfer_evidence_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'transfer-evidence'::text) AND public.can_access_transfer_evidence(name, 'update'::text) AND (lower(storage.extension(name)) = ANY (ARRAY['jpg'::text, 'jpeg'::text, 'png'::text, 'webp'::text])) AND ((metadata ->> 'mimetype'::text) = ANY (ARRAY['image/jpeg'::text, 'image/png'::text, 'image/webp'::text]))));
CREATE POLICY transfer_evidence_read ON storage.objects FOR SELECT TO authenticated USING (((bucket_id = 'transfer-evidence'::text) AND public.can_access_transfer_evidence(name, 'view'::text)));